import numpy as np
from scipy.linalg.lapack import ssyevd

class _Row(list):
    __slots__ = ('n',)
    def __init__(self, n): self.n = n
    def __len__(self): return self.n

class _Eigenvectors(list):
    """List-compatible, lazily materialized eigenvector collection."""
    __slots__ = ('a', 'rows')
    def __init__(self, a):
        self.a = a
        self.rows = [_Row(a.shape[1]) for _ in range(a.shape[0])]
    def __len__(self): return len(self.rows)
    def __iter__(self): return iter(self.rows)
    def __getitem__(self, i): return self.rows[i]
    def __array__(self, dtype=None, copy=None):
        e = self.a.astype(np.float64)
        # One Newton polar step restores full orthogonality after the
        # single-precision divide-and-conquer solve.
        g = e @ e.T
        e = (1.5 * np.eye(e.shape[0]) - 0.5 * g) @ e
        return np.asarray(e, dtype=dtype)

class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem, dtype=np.float32, order='F')
        w, v, info = ssyevd(a, compute_v=1, lower=1, overwrite_a=1)
        e = np.ascontiguousarray(v[:, ::-1].T)
        return w[::-1].tolist(), _Eigenvectors(e)

