import numpy as np
from scipy.linalg import eigh

class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem, dtype=np.float32, order='F')
        w, v = eigh(a, overwrite_a=True, check_finite=False, driver='evd')
