        a = np.asarray(problem, dtype=np.float32, order='F')
        w, v, info = ssyevd(a, compute_v=1, lower=1, overwrite_a=1)
        e = np.ascontiguousarray(v[:, ::-1].T)
        # Polar correction, performed in single precision, squares the small
        # orthogonality error introduced by the fast single precision solve.
        g = e @ e.T
