    try:
        X=np.ndarray(xshape,dtype=np.float64,buffer=sx.buf)
        Q=np.ndarray(qshape,dtype=np.float64,buffer=sq.buf)
        return KernelDensity(kernel=k,bandwidth=h).fit(X).score_samples(Q[lo:hi])
