import numpy as np
from scipy.spatial.distance import cdist
from scipy.special import logsumexp
from sklearn.neighbors._ball_tree import kernel_norm

class Solver:
    def solve(self, problem, **kwargs):
        X = np.asarray(problem['data_points'], dtype=np.float64)
        Q = np.asarray(problem['query_points'], dtype=np.float64)
        if len(Q) == 0:
            return {'log_density': []}
        h = float(problem['bandwidth'])
        kernel = problem['kernel']
        d = X.shape[1]
        # cdist's compiled distance loop is substantially quicker than constructing
        # and querying a Python-level estimator for these moderately sized batches.
        r = cdist(Q, X, metric='euclidean') / h
        if kernel == 'gaussian':
            a = -.5 * r*r
        elif kernel == 'exponential':
            a = -r
        else:
            outside = r > 1.0
            if kernel == 'tophat':
                a = np.zeros_like(r)
            elif kernel == 'epanechnikov':
                with np.errstate(divide='ignore', invalid='ignore'):
                    a = np.log1p(-r*r)
            elif kernel == 'linear':
                with np.errstate(divide='ignore', invalid='ignore'):
                    a = np.log1p(-r)
            elif kernel == 'cosine':
                with np.errstate(divide='ignore', invalid='ignore'):
                    a = np.log(np.cos((np.pi/2)*r))
            a[outside] = -np.inf
        ans = logsumexp(a, axis=1)
        ans += kernel_norm(h, d, kernel, True) - np.log(X.shape[0])
        return {'log_density': ans.tolist()}
