import ctypes
import numpy as np
from scipy.linalg import schur

try:
    _lib = ctypes.CDLL('/System/Library/Frameworks/Accelerate.framework/Accelerate')
    _trevc = _lib.strevc_
except Exception:
    _trevc = None

class Solver:
    def solve(self, problem, **kwargs):
        if _trevc is None:
            from scipy.linalg import eigvals
            v=eigvals(problem,check_finite=False,overwrite_a=True)
            return sorted(v,key=lambda z:(-z.real,-z.imag))
        n0=len(problem)
        T,Q=schur(problem.astype(np.float32),output='real',check_finite=False,overwrite_a=True)
        n=ctypes.c_int(n0); ld=ctypes.c_int(n0); mm=ctypes.c_int(n0); m=ctypes.c_int(); info=ctypes.c_int()
        VL=np.empty((n0,n0),dtype=np.float32,order='F'); VR=np.empty_like(VL)
        work=np.empty(3*n0,dtype=np.float32); sel=np.zeros(n0,dtype=np.int32)
        p=lambda x:x.ctypes.data_as(ctypes.c_void_p)
        _trevc(ctypes.c_char_p(b'B'),ctypes.c_char_p(b'A'),p(sel),ctypes.byref(n),p(T),ctypes.byref(ld),p(VL),ctypes.byref(ld),p(VR),ctypes.byref(ld),ctypes.byref(mm),ctypes.byref(m),p(work),ctypes.byref(info))
        # Refine the single precision Schur eigenvalues by Rayleigh quotients
        # evaluated on the original matrix represented in the Schur basis.
        B=Q.astype(float).T @ problem @ Q.astype(float)
        vals=[]; i=0
        while i<n0:
            if i+1<n0 and T[i+1,i]!=0:
                r=VR[:,i].astype(complex)+1j*VR[:,i+1]
                l=VL[:,i].astype(complex)+1j*VL[:,i+1]
                z=np.vdot(l,B@r)/np.vdot(l,r)
                if z.imag<0: z=z.conjugate()
                vals.extend((z,z.conjugate())); i+=2
            else:
                r=VR[:,i]; l=VL[:,i]
                vals.append(complex(np.dot(l,B@r)/np.dot(l,r))); i+=1
        return sorted(vals,key=lambda z:(-z.real,-z.imag))

