import numpy as np

class Solver:
    def __init__(self):
        self.prob = None
    def solve(self, problem, **kwargs):
        c=np.asarray(problem['c']); A=np.asarray(problem['A']); b=np.asarray(problem['b'])
        m,n=A.shape
